const r = await tools.exec_command({cmd:"python - <<'PY'
import pandas as pd
for fid in ['C','E','I','M','P','R','S','U','W']:
 p=f'dataset/production_FARM_{fid}.csv'; b=open(p,'rb').read(); enc='utf-16' if b[:2] in (b'\xff\xfe',b'\xfe\xff') else 'utf-8-sig'; h=b.decode(enc).splitlines()[3]; sep=';' if h.count(';')>h.count(',') else ','
 d=pd.read_csv(p,encoding=enc,skiprows=3,sep=sep,decimal=',',thousands='.')
 print(fid,d.dtypes.iloc[0],[(repr(c),str(d[c].dtype),repr(d[c].iloc[0])) for c in d.columns if c.strip() in ['timestamp','reading','meter_value','power_out','energy_wh','generation','sensor_out','energy_out','yield_wh']])
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:12000});
text(r.output);

